package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)
	s, _ := reader.ReadString('\n')
	s = s[:len(s)-1] // remove newline
	// read the next line which contains the commands
	commands, _ := reader.ReadString('\n')
	commands = commands[:len(commands)-1] // remove newline

	// precompute prefix sums for x and y
	// each command moves:
	// U: (0, 1)
	// D: (0, -1)
	// R: (1, 0)
	// L: (-1, 0)
	prefixX := make([]int, n+1)
	prefixY := make([]int, n+1)

	for i := 0; i < n; i++ {
		c := commands[i]
		dx, dy := 0, 0
		switch c {
		case 'U':
			dy = 1
		case 'D':
			dy = -1
		case 'R':
			dx = 1
		case 'L':
			dx = -1
		}
		prefixX[i+1] = prefixX[i] + dx
		prefixY[i+1] = prefixY[i] + dy
	}

	count := 0
	for i := 0; i < n; i++ {
		for j := i + 1; j <= n; j++ {
			// substring from i to j-1 (inclusive)
			// displacement is (prefixX[j] - prefixX[i], prefixY[j] - prefixY[i])
			if prefixX[j]-prefixX[i] == 0 && prefixY[j]-prefixY[i] == 0 {
				count++
			}
		}
	}

	fmt.Println(count)
}
